 125	\subsection{Measurements}
 126	
 127	\begin{definition}[Measurements and sub-measurements]
 128	Let $\calH$ be a Hilbert space and $\calA$ be a set of outcomes.
 129	A \emph{sub-measurement}
 130	is a set of Hermitian, positive-semidefinite matrices
 131	$A = \{A_a\}_{a \in \calA}$
 132	acting on~$\calH$
 133	such that $\sum_a A_a \leq I$.
 134	The sub-measurement is \emph{projective} if $(A_a)^2 = A_a$ for each~$a$.
 135	It is a \emph{measurement}
 136	if it satisfies the stronger condition $\sum_a A_a = I$.
 137	\end{definition}
 138	
 139	An important class of sub-measurements
 140	are those that output polynomials~$g$ of individual degree~$d$.
 141	These are defined as follows.
 142	
 143	\begin{definition}[Low-degree polynomial measurements]
 144	We write $\polysub{m}{q}{d}$ for the set of sub-measurements $G=\{G_g\}$
 145	with outcomes $g \in \polyfunc{m}{q}{d}$.
 146	We write $\polymeas{m}{q}{d}$ for the subset of $\polysub{m}{q}{d}$
 147	containing only those $G = \{G_g\}$ which are measurements.
 148	\end{definition}
 149	
 150	\begin{definition}[Post-processing measurements]\label{def:post-processing}
 151	Let $A = \{A_a\}_{a \in \calA}$ be a set of matrices,
 152	and let $f:\calA \rightarrow \calB$ be a function.
 153	Then for each $b \in \calB$,
 154	we define the matrix
 155	\begin{equation*}
 156	A_{[f(a)=b]} = \sum_{a:f(a)=b} A_a.
 157	\end{equation*}
 158	\end{definition}
 159	
 160	\begin{remark}
 161	We note that \Cref{def:post-processing}
 162	agrees with the notation for post-processing measurements
 163	used in \cite{NW19},
 164	but it disagrees with the notation used in \cite{JNV+20}.
 165	That work uses the notation ``$A_{[f(\cdot)=b]}$'' rather
 166	than the notation ``$A_{[f(a)=b]}$'' that we use in this work. 
 167	\end{remark}
 168	
 169	An easy-to-prove fact is that measurements remain measurements after post-processing their outcomes.
 170	
 171	\begin{proposition}
 172	Let $A = \{A_a\}_{a \in \calA}$ be a set of matrices,
 173	and let $f:\calA \rightarrow \calB$ be a function.
 174	Then
 175	\begin{equation*}
 176	\sum_a A_a = \sum_b A_{[f(a)=b]}.
 177	\end{equation*}
 178	Thus, if~$\{A_a\}$ is a sub-measurement (respectively, measurement),
 179	then~$\{A_{[f(a)=b]}\}$ is also a sub-measurement (respectively, measurement).
 180	\end{proposition}
 181	
 182	\begin{remark}
 183	We note that there is some ambiguity in the notation $A_{[f(a)=b]}$
 184	because it requires one to know which of~$f$ or~$a$ is the measurement outcome
 185	and which is the function applied to it.
 186	For example, given a sub-measurement $G = \{G_g\} \in \polysub{m}{q}{d}$,
 187	we will often consider evaluating its outputs at a point $u \in \F_q^m$.
 188	This entails looking at the sub-measurement
 189	\begin{equation*}
 190	\{G_{[g(u)=a]}\}_{a \in \F_q},
 191	\quad
 192	\text{where}
 193	\quad
 194	G_{[g(u)=a]} = \sum_{g:g(u) = a} G_g.
 195	\end{equation*}
 196	Here, $g$ is the measurement outcome of~$G$,
 197	and the function being applied maps it to its evaluation on the point~$u$, i.e.\ $g(u)$.
 198	In general, it should always be clear from context
 199	what the measurement outcome and the function being applied to it are.
 200	\end{remark}
 201	
 202	\begin{notation}[Measurements indexed by questions]
 203	We will frequently encounter sets of sub-measurements $A^x= \{A^x_{a}\}$ indexed by elements~$x$ from a set of ``questions" $\calX$. We will write $A = \{A^x_a\}$ for this set. 
 204	We will typically refer to this set~$A$ as a sub-measurement,
 205	and we will refer to it as a measurement if each~$A^x$ is a measurement.
 206	In addition, we will refer to it as projective if each~$A^x$ is projective.
 207	\end{notation}
 208	
 209	\begin{notation}[Complete part of sub-measurement]
 210	Given a sub-measurement~$A = \{A_a\}$, we will write $A = \sum_a A_a$.
 211	Similarly, given a sub-measurement~$A = \{A^x_a\}$, we will write $A^x = \sum_a A^x_a$ and $A = \E_{\bx} A^{\bx}$.
 212	\end{notation}
 213	
 214	The complete part of a sub-measurement
 215	contrasts with its \emph{incomplete part},
 216	which is the matrix $I - A^x$.
 217	We will sometimes
 218	view~$A$ as a measurement
 219	by throwing in its incomplete part as an additional POVM element.
 220	This is formalized in the following definition.
 221	
 222	
 223	\begin{definition}[Completing a sub-measurement]\label{def:measurement-completion}
 224	Let $A = \{A^x_a\}_{a \in \calA}$ be a sub-measurement.
 225	We define the \emph{completion of~$A$},
 226	denoted $\mathrm{completion}(A)$,
 227	to be the measurement $\widehat{A} = \{\widehat{A}^x_a\}$
 228	with outcome set $\widehat{\calA} = \calA \cup \{\bot\}$ 
 229	such that for each $a \in \widehat{\calA}$,
 230	\begin{equation*}
 231	A^x_a
 232	= \left\{\begin{array}{cl}
 233			A^x_a & \text{if $a \in \calA$,}\\
 234			I - A^x & \text{if $a = \bot$}.
 235			\end{array}\right.
 236	\end{equation*}
 237	\end{definition}
