 472	\subsubsection{Deriving consistency relations from the state-dependent distance}
 473	\label{sec:consistency-from-state-dependent-distance}
 474	
 475	\Cref{prop:triangle-sub} shows the purpose of the state-dependent distance,
 476	which is to derive new consistency relations from old ones.
 477	In addition, its proof uses a strategy
 478	which will recur frequently throughout this paper.
 479	In this strategy, we would like to demonstrate a sequence of 
 480	expressions in which each expression is close to the previous one:
 481	\begin{equation*}
 482	\E_{\bx} \sum_a \bra{\psi} (A_0)^{\bx}_a (B_0)^{\bx}_a \ket{\psi}
 483	\approx_{\eps_1} \E_{\bx} \sum_a \bra{\psi} (A_1)^{\bx}_a (B_1)^{\bx}_a \ket{\psi}
 484	\approx_{\eps_2} \cdots
 485	\approx_{\eps_t} \E_{\bx} \sum_a \bra{\psi} (A_t)^{\bx}_a (B_t)^{\bx}_a \ket{\psi}.
 486	\end{equation*}
 487	By the triangle inequality, we can therefore conclude that the $0$-th expression
 488	is close to the $t$-th expression.
 489	To show that the $i$-th quantity is close to the $(i+1)$-st,
 490	we will typically arrange for $A_{i} = A_{i+1}$,
 491	and we will swap out $B_i$ for $B_{i+1}$
 492	using an approximation relation such as $(B_i)^x_a \approx (B_{i+1})^x_a$,
 493	with the help of the Cauchy-Schwarz inequality
 494	(or the same might occur with the roles of~$A$ and~$B$ reversed). 
 495	Even if $A_0$ and $B_0$ can be written as local measurements applied to either side of a bipartition,
 496	e.g.\ $(A_0)^x_a = A^x_a \ot I$ and $(B_0)^x_a = I \ot B^x_a$,
 497	and likewise for $A_t$ and $B_t$,
 498	the intermediate steps may feature matrices which do not decompose nicely across a bipartition.
 499	This is why \Cref{def:approx_delta} is phrased so broadly,
 500	with no mention of a bipartition.
 501	
 502	In general, the $A_i$'s and $B_i$'s encountered in this sequence of steps
 503	may be quite unstructured: for example, not sub-measurements,
 504	and possibly not even Hermitian.
 505	Thus, we are interested in determining which conditions
 506	to place on these measurements are sufficient to carry out this proof strategy.
 507	The following proposition gives a broad condition under which this can be accomplished.
 508	
 509	\begin{proposition}
 510	\label{prop:closeness-of-ip}
 511		Let $\{A^x_a\}$, $\{B^x_a\}$, and $\{C^x_{a,b} \}$ be matrices.
 512		Suppose that  $A^x_a \approx_\gamma B^x_a$ and that for all~$x$, $\sum_a (\sum_b C^x_{a,b}) (\sum_b C^x_{a,b})^\dagger  \leq I$. Then
 513		\begin{equation}
 514		\E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} A^{\bx}_a  \ket{\psi} \approx_{\sqrt{\gamma}} \E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} B^{\bx}_a  \ket{\psi} \,. \label{eq:closeness3}
 515		\end{equation}
 516		Similarly, suppose that  $(A^x_a)^\dagger \approx_\gamma (B^x_a)^\dagger$ and that for all~$x$, $\sum_a (\sum_b C^x_{a,b})^\dagger (\sum_b C^x_{a,b}) \leq I$. Then 
 517		\begin{equation}
 518		\E_{\bx} \sum_{a,b} \bra{\psi} A^{\bx}_a  C^{\bx}_{a,b} \ket{\psi} \approx_{\sqrt{\gamma}} \E_{\bx} \sum_{a,b} \bra{\psi} B^{\bx}_a  C^{\bx}_{a,b}  \ket{\psi} \,. \label{eq:closeness4}
 519		\end{equation}	
 520	\end{proposition}
 521	\begin{proof}
 522		We begin by showing~\Cref{eq:closeness3}.
 523		\begin{align*}
 524			&\Big | \E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \Big | \\
 525			&= \Big | \E_{\bx} \sum_{a} \bra{\psi} \Big ( \sum_b C^{\bx}_{a,b} \Big ) \cdot (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \Big |\\
 526			&\leq \Big ( \E_{\bx} \sum_a \bra{\psi} \Big(\sum_b C^{\bx}_{a,b}\Big) \Big(\sum_b C^{\bx}_{a,b}\Big)^\dagger \ket{\psi} \Big )^{1/2} \cdot \Big ( \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^\dagger  (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \Big)^{1/2} \\
 527			&\leq \sqrt{\gamma}.
 528		\end{align*}
 529		The third line uses Cauchy-Schwarz, and the fourth line uses the assumption $\sum_a (\sum_b C^x_{a,b}) (\sum_b C^x_{a,b})^\dagger  \leq I$ to bound the first factor by $1$ and  the assumption $A^x_a \approx_\gamma B^x_a$ to bound the second factor by $\sqrt{\gamma}$.
 530		As for \Cref{eq:closeness4}, we want to bound
 531		\begin{equation*}
 532		\Big | \E_{\bx} \sum_{a,b} \bra{\psi} (A^{\bx}_a - B^{\bx}_a) C^{\bx}_{a,b}  \ket{\psi} \Big |
 533		= \Big | \E_{\bx} \sum_{a,b} \bra{\psi} (C^{\bx}_{a,b})^\dagger ((A^{\bx}_a)^\dagger - (B^{\bx}_a)^\dagger) \ket{\psi} \Big |.
 534	      \end{equation*}
 535	      It then follows from \Cref{eq:closeness3} that this is at most $\sqrt{\gamma}$.
 536	    \end{proof}
 537	    
 538	\Cref{prop:closeness-of-ip} is broad enough to capture
 539	almost all of our applications of the state-dependent distance.
 540	Unfortunately, defining the $C^x_{a, b}$ matrices and showing that 
 541	they satisfy the inequality $\sum_a (\sum_b C^x_{a,b}) (\sum_b C^x_{a,b})^\dagger  \leq I$
 542	can be somewhat cumbersome.
 543	As a result, we will usually carry out these Cauchy-Schwarz calculations by hand.
 544	However, we will occasionally use the following proposition
 545	which simplifies \Cref{prop:closeness-of-ip}.
 546	
 547	\begin{proposition}\label{prop:easy-approx-from-approx-delta}
 548	Let $A = \{A^x_a\}$, $B = \{B^x_a\}$, and $C = \{C^x_a\}$ be sub-measurements
 549	such that $A^x_a \approx_{\delta} B^x_a$. Then
 550	\begin{equation*}
 551	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a  C^{\bx}_a \ket{\psi}
 552	\approx_{\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a  C^{\bx}_a \ket{\psi}.
 553	\end{equation*}
 554	\end{proposition}
 555	\begin{proof}
 556	To show this, we bound the magnitude of the difference.
 557	\begin{align*}
 558	&\Big| \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a) \cdot (C^{\bx}_a) \ket{\psi}\Big|\\
 559	\leq~& \sqrt{\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^2 \ket{\psi}}
 560		\cdot \sqrt{\E_{\bx} \sum_a \bra{\psi} (C^{\bx}_a)^2 \ket{\psi}}\\
 561	\leq~& \sqrt{\delta} \cdot \sqrt{1}.
 562	\end{align*}
 563	This completes the proof.
 564	\end{proof}
 565	
 566	A proposition similar to \Cref{prop:closeness-of-ip},
 567	but for  ``$\approx$'',
 568	holds as well.
 569	    This is \cite[Fact~$4.20$]{NW19}.
 570	    \begin{proposition}
 571	      \label{prop:cab-approx-delta}
 572	      Let $\{A^x_a\}, \{B^x_a\},$ and $\{C^x_{a,b}\}$ be
 573	      matrices. Suppose that $A^{x}_a \approx_\delta B^{x}_a$ and that
 574	      for all $x$ and $a$, $\sum_b (C^{x}_{a,b})^\dagger
 575	      (C^{x}_{a,b}) \leq I$. Then
 576	      \[ C^{x}_{a,b} A^x_{a} \approx_{\delta} C^{x}_{a,b} B^{x}_a. \]
 577	    \end{proposition}
 578	    \begin{proof}
 579	      The error we wish to bound is
 580	      \begin{align*}
 581	        \E_{\bx} \sum_{a,b} \bra{\psi} 
 582	        (A^{\bx}_a - B^{\bx}_a)^\dagger
 583	        (C^{\bx}_{a,b})^\dagger C^{\bx}_{a,b} (A^{\bx}_a - 
 584	        B^{\bx}_a) \ket{\psi} &\leq \E_{\bx} \sum_{a} \bra{\psi}
 585	                                (A^{\bx}_a - B^{\bx}_a)^\dagger
 586	                                (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \\
 587	                              &\leq \delta. \qedhere
 588	      \end{align*}
 589	    \end{proof}
