 592	\subsubsection{Miscellaneous distance properties}
 593	
 594	We now state a few miscellaneous properties of our two distances.
 595	
 596	\begin{proposition}[Triangle inequality for vectors squared]\label{prop:triangle-inequality-for-vectors-squared}
 597	Let $\ket{\psi_1}, \ldots, \ket{\psi_k}$ be vectors.
 598	Then
 599	\begin{equation*}
 600	\Vert \ket{\psi_1} + \cdots + \ket{\psi_k} \Vert^2 \leq k \cdot(\Vert \ket{\psi_1}\Vert^2 + \cdots + \Vert \ket{\psi_k}\Vert^2).
 601	\end{equation*}
 602	\end{proposition}
 603	\begin{proof}
 604	First, if $x_1, \ldots, x_k \in \R$, then
 605	\begin{equation}\label{eq:prop-for-real-numbers}
 606	(x_1 + \cdots + x_k)^2 
 607	= \sum_{i, j= 1}^k x_i x_j
 608	\leq \sum_{i, j= 1}^k \frac{x_i^2 + x_j^2}{2}
 609	= \sum_{i, j= 1}^k x_i^2
 610	= \sum_{i=1}^k k \cdot x_i^2.
 611	\end{equation}
 612	Next, by the triangle inequality
 613	\begin{align*}
 614	\Vert \ket{\psi_1} + \cdots + \ket{\psi_k} \Vert^2
 615	& = (\Vert \ket{\psi_1} + \cdots + \ket{\psi_k} \Vert)^2\\
 616	& \leq (\Vert \ket{\psi_1}\Vert + \cdots + \Vert \ket{\psi_k} \Vert)^2\\
 617	& \leq k \cdot(\Vert \ket{\psi_1}\Vert^2 + \cdots + \Vert \ket{\psi_k}\Vert^2).
 618	\end{align*}
 619	where the last step uses \Cref{eq:prop-for-real-numbers} applied to the case of $x_i = \Vert \ket{\psi_i}\Vert$.
 620	\end{proof}
 621	
 622	\begin{proposition}[Triangle inequality for ``$\approx_{\delta}$"]
 623	\label{prop:triangle-inequality-for-approx_delta}
 624	Suppose $A_1 = \{(A_1)^x_a\}, \ldots, A_{k+1} = \{(A_{k+1})^x_a\}$ is a set of matrices such that
 625	\begin{equation*}
 626	(A_i)^x_a \approx_{\delta_i} (A_{i+1})^x_a
 627	\end{equation*}
 628	for all $i \in [k]$. Then
 629	\begin{equation*}
 630	(A_1)^x_a \approx_{k \cdot (\delta_1 + \cdots + \delta_{k})} (A_{k+1})^x_a.
 631	\end{equation*}
 632	\end{proposition}
 633	\begin{proof}
 634	We want to bound
 635	\begin{align*}
 636	&~\E_\bx \sum_a \Vert ((A_1)^{\bx}_a - (A_{k+1})^{\bx}_a) \ket{\psi}\Vert^2\\
 637	= &~\E_\bx \sum_a \Vert (((A_1)^{\bx}_a - (A_2)^{\bx}_a) + \cdots.+ ((A_{k})^{\bx}_a - (A_{k+1})^{\bx}_a))\ket{\psi}\Vert^2\\
 638	\leq &~\E_\bx \sum_a k\cdot(\Vert ((A_1)^{\bx}_a - (A_2)^{\bx}_a) \ket{\psi}\Vert^2 + \cdots.+ \Vert((A_k)^{\bx}_a - (A_{k+1})^{\bx}_a)\ket{\psi}\Vert^2)\\
 639	\leq &~k\cdot(\delta_1 + \cdots + \delta_{k}),
 640	\end{align*}
 641	where the inequality uses \Cref{prop:triangle-inequality-for-vectors-squared} applied to the vectors $((A_i)^{\bx}_a - (A_{i+1})^{\bx}_a) \ket{\psi}$ for $i \in [k]$.
 642	\end{proof}
 643	
 644	We note that \Cref{prop:triangle-inequality-for-approx_delta}
 645	contrasts with the triangle inequality for ``$\approx_{\delta}$'' when applied to numbers,
 646	i.e.\ \Cref{eq:triangle-inequality-for-numbers},
 647	for which no multiplicative factor of~$k$ appears in the error.
 648	
 649	The following is Fact~$4.29$ from~\cite{NW19};
 650	however, they incorrectly claimed a final bound of $A^x_a \ot I \simeq_{\eps +\delta + \gamma} I \ot D^x_a$.
 651	We give a new proof of this statement, albeit with a slightly weaker quantitative bound.
 652	
 653	\begin{proposition}[Triangle inequality for ``$\simeq$"]\label{prop:simeq-triangle-inequality}
 654			Suppose that $A$, $B$, $C$, and~$D$ are measurements such that
 655			\begin{equation*}
 656			A^x_a \ot I \simeq_{\eps} I \ot B^x_a,
 657			\quad
 658			C^x_a \ot I \simeq_{\delta} I \ot B^x_a,
 659			\quad
 660			C^x_a \ot I \simeq_{\gamma} I \ot D^x_a.
 661			\end{equation*}
 662			Then
 663			\begin{equation*}
 664			A^x_a \ot I \simeq_{\eps + 2\sqrt{\delta + \gamma}} I \ot D^x_a.
 665			\end{equation*}
 666			\end{proposition}
 667	\begin{proof}
 668	Because $B$, $C$, and~$D$ are measurements, \Cref{prop:simeq-to-approx} implies that
 669	\begin{equation*}
 670	C^x_a \ot I \approx_{2\delta} I \ot B^x_a,
 671	\quad
 672	C^x_a \ot I \approx_{2\gamma} I \ot D^x_a.
 673	\end{equation*}
 674	The triangle inequality, \Cref{prop:triangle-inequality-for-approx_delta}, then implies that
 675	\begin{equation*}
 676	I \ot B^x_a \approx_{4 \delta + 4 \gamma} I \ot D^x_a.
 677	\end{equation*}
 678	Finally, \Cref{prop:triangle-sub} implies that
 679	\begin{equation*}
 680	A^x_a \ot I
 681	\simeq_{\eps + \sqrt{4 \delta + 4 \gamma}} I \ot D^x_a.
 682	\end{equation*}
 683	This completes the proof.
 684	\end{proof}
 685	
 686	\begin{proposition}[Data processing for ``$\simeq$'']
 687	\label{prop:simeq-data-processing}
 688	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be two measurements such that
 689	\begin{equation*}
 690	A^x_a \ot I \simeq_{\delta} I \ot B^x_a.
 691	\end{equation*}
 692	Then for any function~$f$,
 693	\begin{equation*}
 694	A^x_{[f(a)=b]} \ot I \simeq_{\delta} I \ot B^x_{[f(a)=b]}.
 695	\end{equation*}
 696	\end{proposition}
 697	\begin{proof}
 698	We want to bound
 699	\begin{align*}
 700	\E_{\bx} \sum_{b \neq b'} \bra{\psi} A^{\bx}_{[f(a)=b]} \ot B^{\bx}_{[f(a)=b']}\ket{\psi}
 701	& = \E_{\bx} \sum_{b \neq b'} \sum_{a: f(a) = b} \sum_{a': f(a') = b'} \bra{\psi} A^{\bx}_{a} \ot B^{\bx}_{a'}\ket{\psi}\\
 702	& \leq \E_{\bx} \sum_{a \neq a'} \bra{\psi} A^{\bx}_{a} \ot B^{\bx}_{a'}\ket{\psi}\\
 703	& \leq \delta.
 704	\end{align*}
 705	This completes the proof.
 706	\end{proof}
 707	    
 708	The following fact is useful for translating between statements about consistency and closeness between sub-measurements.
 709	\begin{proposition}
 710	\label{prop:cons-sub-meas} 
 711	Let $\{A^x_a\}$ be a sub-measurement and let $\{B^x_a\}$ be a measurement such that on average over $x$,
 712	\[
 713		A^x_a \ot I \simeq_\gamma I \ot B^x_a \,.
 714	\]
 715	Then the following hold
 716		\begin{gather}
 717			A^x_a \ot I \approx_{\gamma} A^x_a \ot B^x_a \approx_{\gamma} A^x \ot B^x_a,
 718			\label{eq:closeness5}
 719		\end{gather}
 720		where $A^x = \sum_a A^x_a$.
 721		As a result, by \Cref{prop:triangle-inequality-for-approx_delta},
 722		\begin{equation*}
 723		A^x_a \ot I \approx_{4\gamma} A^x \ot B^x_a
 724		\end{equation*}
 725	\end{proposition}
 726	\begin{proof}
 727		We establish the first approximation in \Cref{eq:closeness5}:
 728		\begin{align*}
 729			&\E_{\bx} \sum_a \bra{\psi} \Big (A^{\bx}_a \ot (I - B^{\bx}_a) \Big)^2 \ket{\psi}  \\
 730			&\leq \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot (I - B^{\bx}_a) \ket{\psi} \\
 731			&= \E_{\bx} \sum_{\substack{a,b : \\ b \neq a}} \bra{\psi} A^{\bx}_a \ot B^{\bx}_b \ket{\psi} \\
 732			&\leq \gamma \,.
 733		\end{align*}
 734		The first inequality folows from the fact that $A^x_a \ot (I - B^x_a)$ has operator norm at most $1$, and the third line follows from the fact that $\{B^x_b\}$ is a complete measurement, and the last line follows from the assumption of consistency between the $A$ and $B$ (sub-)measurements.
 735		
 736		To establish the second approximation in \Cref{eq:closeness5}, we compute the difference:
 737		\begin{align*}
 738		&\E_{\bx} \sum_a \bra{\psi} \Big ( (A^{\bx} - A^{\bx}_a) \ot B^{\bx}_a \Big)^2 \ket{\psi} \\
 739		&\leq  \E_{\bx} \sum_a \bra{\psi} (A^{\bx} - A^{\bx}_a) \ot B^{\bx}_a  \ket{\psi} \\
 740		&= \E_{\bx} \sum_{\substack{a,a' : \\ a \neq a'}} \bra{\psi} A^{\bx}_{a'} \ot B^{\bx}_a  \ket{\psi} \\
 741		&\leq \gamma \,.
 742		\end{align*}
 743		The second line follows from the fact that  $(A^x - A^x_a) \ot B^x_a$ has operator norm at most $1$, and the last inequality follows from the consistency between the $A$ and $B$ (sub-)measurements.
 744	\end{proof}
 745	
 746	
 747	
 748	\begin{proposition}  \label{prop:switch-sandwich}
 749	  Suppose $\{A^x_a\}$ is a projective sub-measurement
 750	  satisfying
 751	  \begin{equation}
 752	    A^x_a \ot I \approx_{\delta} I \ot A^x_a. \label{eq:Aapproxd}
 753	  \end{equation}
 754	  Then for any $0 \leq B \leq I$, the following holds:
 755	  \begin{equation}
 756	    \E_{\bx}\sum_a \bra{\psi} A^{\bx}_a B A^{\bx}_a \ot I \ket{\psi}
 757	    \approx_{2\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi} B
 758	    \ot A^{\bx}_a
 759	    \ket{\psi} \approx_{\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi}
 760	    BA^{\bx}_a \ot I \ket{\psi} \label{eq:switch-sandwich} \end{equation}
 761	
 762	\end{proposition}
 763	\begin{proof}
 764	  We will show the first approximation in \Cref{eq:switch-sandwich} in two steps. First, we show that
 765	  \begin{equation} \label{eq:shift-right-A}
 766	    \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a B A^{\bx}_a \ot I \ket{\psi} \approx_{\sqrt{\delta}}
 767	    \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a B \ot A^{\bx}_a \ket{\psi}.
 768	  \end{equation}
 769	  To do so, we bound the magnitude of the difference.
 770	  \begin{align*}
 771	   &\Big| \E_{\bx}\sum_a \bra{\psi} (A^{\bx}_a B \otimes I)\cdot (A^{\bx}_a \ot I  - I \ot A^{\bx}_a)  \ket{\psi} \Big|\\
 772	    \leq~&
 773	    \Big( \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a
 774	                 B^2
 775	                 A^{\bx}_a \otimes I \ket{\psi} \Big)^{1/2}  
 776	                \cdot \Big(\E_{\bx} \sum_a
 777	                 \bra{\psi} (A^{\bx}_a \ot I - I \ot A^{\bx}_a)^2
 778	                 \ket{\psi} \Big)^{1/2} \\
 779	               \leq~& \sqrt{\delta}.\tag{because $B \leq I$ and \eqref{eq:Aapproxd}}
 780	  \end{align*}
 781	  Next, we show that
 782	  \begin{equation*}
 783	  \eqref{eq:shift-right-A} =  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a B \ot A^{\bx}_a \ket{\psi} \approx_{\sqrt{\delta}} \E_{\bx} \sum_ a\bra{\psi} B \ot A^{\bx}_a \ket{\psi}.
 784	  \end{equation*}
 785	  To do so, we bound the magnitude of the difference.
 786	  \begin{align*}
 787	    &\Big|\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a \ot I - I \ot A^{\bx}_a) \cdot(B
 788	    \ot A^{\bx}_a) \ket{\psi}\Big| \tag{because~$A$ is projective}\\ \leq~& \Big( \E_{\bx} \sum_a \bra{\psi}
 789	                               (A^{\bx}_a \ot I - I \ot A^{\bx}_a)^2
 790	                               \ket{\psi} \Big)^{1/2}  
 791	                              \cdot \Big(\E_{\bx} \sum_a
 792	                               \bra{\psi} B^2 \ot A^{\bx}_a \ket{\psi}
 793	                               \Big)^{1/2} \\
 794	                             \leq~& \sqrt{\delta}.\tag{because $B \leq I$ and \eqref{eq:Aapproxd}}
 795	  \end{align*}
 796	  Thus, the first approximation in \Cref{eq:switch-sandwich}
 797	  follows. To show the second approximation, we bound the magnitude of the difference.
 798	  \begin{align*}
 799	  &\Big|\E_{\bx}\sum_a \bra{\psi} (B\otimes I)  \cdot ( A^{\bx}_a \ot I - I \ot A^{\bx}_a )
 800	    \ket{\psi}\Big|\\
 801	    =~&\Big|\E_{\bx} \bra{\psi} (B\otimes I)\cdot \sum_a ( A^{\bx}_a \ot I - I \ot A^{\bx}_a )
 802	    \ket{\psi}\Big|\\
 803	    \leq~& \Big( \E_{\bx} \bra{\psi} B^2 \otimes I \ket{\psi} \Big)^{1/2}
 804	    \cdot \Big( \E_{\bx} \sum_{a,b} \bra{\psi}
 805	    (A^{\bx}_a \ot I - I \ot A^{\bx}_a) \cdot(A^{\bx}_b \ot I
 806	    - I \ot A^{\bx}_b) \ket{\psi} \Big)^{1/2}.
 807	  \end{align*}
 808	  The first term in the product is at most $1$ because $B \leq I$.
 809	  We bound the expression inside the second square root as follows.
 810	  \begin{align*}
 811	    &\E_{\bx} \sum_{a,b} \bra{\psi}    (A^{\bx}_a \ot I - I \ot A^{\bx}_a) \cdot(A^{\bx}_b \ot I
 812	    - I \ot A^{\bx}_b) \ket{\psi}  \\
 813	    =~&\E_{\bx} \sum_{a, b} \bra{\psi}(A^{\bx}_a A^{\bx}_b \ot I + I \otimes A^{\bx}_a A^{\bx}_b - A^{\bx}_a \otimes A^{\bx}_b - A^{\bx}_b \otimes A^{\bx}_a)\ket{\psi}\\
 814	    =~& \E_{\bx}\sum_a
 815	                                                \bra{\psi} (A^{\bx}_a)^2
 816	                                                \ot I \ket{\psi} +
 817	                                                 \E_{\bx}\sum_a
 818	                                                \bra{\psi} I \ot (A^{\bx}_a)^2 \ket{\psi} -
 819	                                                 2\cdot\E_{\bx} \sum_{a,b} \bra{\psi}A^{\bx}_a
 820	                                                \ot A^{\bx}_b
 821	                                                \ket{\psi} \tag{because~$A$ is projective}
 822	                                                \\
 823	    \leq~& \E_{\bx}\sum_a
 824	                                                \bra{\psi} (A^{\bx}_a)^2
 825	                                                \ot I \ket{\psi} +
 826	                                                 \E_{\bx}\sum_a
 827	                                                \bra{\psi} I \ot (A^{\bx}_a)^2 \ket{\psi} -
 828	                                                 2\cdot\E_{\bx} \sum_{a} \bra{\psi}A^{\bx}_a
 829	                                                \ot A^{\bx}_a
 830	                                                \ket{\psi}
 831	                                                \\
 832	       =~& \E_{\bx}\sum_a
 833	                                                \bra{\psi} (A^{\bx}_a
 834	                                                \ot I  - I \ot A^{\bx}_a)^2
 835	                                                \ket{\psi}
 836	       \\
 837	   \leq~& \delta,
 838	  \end{align*}
 839	  where the last step uses \Cref{eq:Aapproxd}.
 840	\end{proof}
 841	
 842	\begin{proposition}\label{prop:completeness-transfer-projective-P}
 843	Let $A = \{A^x_a\}$ be a sub-measurement 
 844	and let $P$ be a projective sub-measurement such that $A^x_a \ot I \approx_{\eps} P_a^x \ot I$.
 845	Then
 846	\begin{equation*}
 847	\bra{\psi} A \ot I \ket{\psi}
 848	\geq  \bra{\psi} P \ot I \ket{\psi} - 2\sqrt{\eps}.
 849	\end{equation*}
 850	\end{proposition}
 851	\begin{proof}
 852	We calculate:
 853	\begin{align*}
 854	\bra{\psi} P \ot I \ket{\psi}
 855	&= \E_{\bx} \sum_a \bra{\psi} P^{\bx}_a \ot I \ket{\psi} \\
 856	&= \E_{\bx} \sum_a \bra{\psi} (P^{\bx}_a)^2 \ot I \ket{\psi} \tag{because~$P$ is projective}\\
 857	&\approx_{\sqrt{\eps}} \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a \cdot P^{\bx}_a) \ot I \ket{\psi}
 858										\tag{by \Cref{prop:easy-approx-from-approx-delta}} \\
 859	&\approx_{\sqrt{\eps}} \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a)^2 \ot I \ket{\psi}
 860										\tag{by \Cref{prop:easy-approx-from-approx-delta}} \\
 861	&\leq \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot I \ket{\psi}\\
 862	& = \bra{\psi} A \ot I \ket{\psi}.
 863	\end{align*}
 864	This completes the proof.
 865	\end{proof}
