 867	\subsubsection{Strong self-consistency}
 868	
 869	An important property of a sub-measurement~$A = \{A^x_a\}$
 870	is that if both provers measure using~$A$,
 871	then they receive the same outcome.
 872	It seems natural to study this using \emph{self-consistency} of~$A$, i.e. the number~$\delta$ such that
 873	\begin{equation*}
 874	A^x_a \ot I \simeq_{\delta} I \ot A^x_a.
 875	\end{equation*}
 876	However, when~$A$ is a sub-measurement,
 877	being $\delta$-self consistent
 878	only implies the following weaker condition:
 879	if both provers measure using~$A$ and one of them receives~$\ba$,
 880	then the other will most likely either receive~$\ba$ \emph{or not receive any outcome whatsoever}.
 881	This motivates defining the following stronger notion of self-consistency.
 882	
 883	\begin{definition}[Strong self consistency]\label{def:strong-self-consistency}
 884	Let $\ket{\psi}$ be a permutation-invariant state in $\calH \ot \calH$
 885	and let $A = \{A^x_a\}$ be a sub-measurement acting on~$\calH$.
 886	Then $A$ is \emph{$\delta$-strongly self consistent} if
 887	\begin{equation*}
 888	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}
 889	\geq
 890	\bra{\psi} A \otimes I \ket{\psi} -  \delta.
 891	\end{equation*}
 892	\end{definition}
 893	
 894	We now relate strong self-consistency to our two notions of similarity.
 895	First, we show that strong self-consistency is indeed
 896	a stronger condition than $A^x_a \ot I \simeq_{\delta} I \ot A^x_a$,
 897	at least for sub-measurements.
 898	
 899	\begin{proposition}\label{prop:other-two-notions-of-self-consistency}
 900	Let $\ket{\psi}$ be a permutation-invariant state,
 901	and let $A = \{A^x_a\}$ be a sub-measurement. If
 902	\begin{equation*}
 903	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq \bra{\psi} A \otimes I \ket{\psi} - \delta
 904	\end{equation*}
 905	then $A^x_a \otimes I \simeq_{\delta} I \otimes A^x_a$.
 906	This is an ``if and only if" if $A$ is a measurement.
 907	\end{proposition}
 908	\begin{proof}
 909	For a sub-measurement~$A$,
 910	\begin{align*}
 911	&\E_{\bx} \sum_{a \neq b} \bra{\psi} A^{\bx}_a \ot A^{\bx}_b \ket{\psi}\\
 912	=~& \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot (A^{\bx}- A^{\bx}_a) \ket{\psi}\\
 913	\leq~&\E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot (I- A^{\bx}_a) \ket{\psi}\\
 914	=~&\E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot I \ket{\psi}
 915			- \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot A^{\bx}_a \ket{\psi}\\
 916	=~& \bra{\psi} A \ot I \ket{\psi}
 917			- \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot A^{\bx}_a \ket{\psi}.
 918	\end{align*}
 919	This is at most~$\delta$ if $A$ is $\delta$-strongly self-consistent.
 920	On the other hand, if~$A$ is a measurement, then the inequality becomes an equality.
 921	Hence, if $A^x_a \ot I \simeq_{\delta} I \otimes A^x_a$,
 922	then $A$ is $\delta$-strongly self-consistent.
 923	\end{proof}
 924	
 925	Next, we show that strong self-consistency is also a stronger 
 926	condition than $A^x_a \ot I \approx_{2\delta} I \ot A^x_a$, at least for non-projective measurements.
 927	
 928	\begin{proposition}\label{prop:two-notions-of-self-consistency}
 929	Let $\ket{\psi}$ be a permutation-invariant state,
 930	and let $A = \{A^x_a\}$ be a sub-measurement. If
 931	\begin{equation*}
 932	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq \bra{\psi} A \otimes I \ket{\psi} - \delta
 933	\end{equation*}
 934	then $A^x_a \otimes I \approx_{2\delta} I \otimes A^x_a$.
 935	This is an ``if and only if" if $A$ is projective.
 936	\end{proposition}
 937	\begin{proof}
 938	For general (i.e.\ not necessarily projective)~$A$
 939	\begin{align}
 940	&\E_{\bx} \sum_a \Vert(A^{\bx}_a \otimes I - I \otimes A^{\bx}_a) \ket{\psi}\Vert^2\nonumber\\
 941	=~&\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a \otimes I - I \otimes A^{\bx}_a)^2 \ket{\psi}\nonumber\\
 942	=~&2\cdot \Big( \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a)^2 \otimes I \ket{\psi} -  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}\Big)\nonumber\\
 943	\leq~&2\cdot \Big( \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes I \ket{\psi} -  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}\Big).\label{eq:here's-where-projectivity-would-help}
 944	\end{align}
 945	This is at most~$2\cdot \delta$ if
 946	\begin{equation*}
 947	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes I \ket{\psi} - \delta.
 948	\end{equation*}
 949	If~$A$ is projective, then \Cref{eq:here's-where-projectivity-would-help} becomes an equality,
 950	and so $A^x_a \otimes I \approx_{2\delta} I \otimes A^x_a$ implies that
 951	\begin{equation*}
 952	 \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes I \ket{\psi} -  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}
 953	 = \frac{1}{2} \cdot \left(\E_{\bx} \sum_a \Vert(A^{\bx}_a \otimes I - I \otimes A^{\bx}_a) \ket{\psi}\Vert^2\right) \leq \delta.\qedhere
 954	\end{equation*}
 955	\end{proof}
 956	
 957	Hence, we may also refer to the condition $A^x_a \ot I \approx_{2\delta} I \ot A^x_a$
 958	as ``strong self-consistency'' if~$A$ is projective.
 959	
 960	For the remainder of the section, we will prove various properties of strongly self-consistent sub-measurements.
 961	
 962	\begin{proposition}\label{prop:two-notions-of-self-consistency-after-evaluation}
 963	Let $\ket{\psi}$ be a permutation-invariant state,
 964	and let $A = \{A^x_a\}$ be a sub-measurement such that
 965	\begin{equation*}
 966	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq  \bra{\psi} A \otimes I \ket{\psi} - \delta.
 967	\end{equation*}
 968	Then for any function~$f$,
 969	$A^x_{[f(a)=b]} \otimes I \approx_{2\delta} I \otimes A^x_{[f(a)=b]}$.
 970	\end{proposition}
 971	\begin{proof}
 972	Our goal is to bound
 973	\begin{align}
 974	&\E_{\bx} \sum_b \Vert(A^{\bx}_{[f(a)=b]} \otimes I - I \otimes A^{\bx}_{[f(a)=b]}) \ket{\psi}\Vert^2\nonumber\\
 975	=~&\E_{\bx} \sum_b \bra{\psi} (A^{\bx}_{[f(a)=b]} \otimes I - I \otimes A^{\bx}_{[f(a)=b]})^2 \ket{\psi}\nonumber\\
 976	=~&2\cdot \Big( \E_{\bx} \sum_b \bra{\psi} (A^{\bx}_{[f(a)=b]})^2 \otimes I \ket{\psi} -  \E_{\bx} \sum_b \bra{\psi} A^{\bx}_{[f(a)=b]} \otimes A^{\bx}_{[f(a)=b]} \ket{\psi}\Big)\nonumber\\
 977	\leq~&2\cdot \Big( \E_{\bx} \sum_b \bra{\psi} A^{\bx}_{[f(a)=b]} \otimes I \ket{\psi} -  \E_{\bx} \sum_b \bra{\psi} A^{\bx}_{[f(a)=b]} \otimes A^{\bx}_{[f(a)=b]} \ket{\psi}\Big).\nonumber\\
 978	=~&2\cdot \Big(  \bra{\psi} A \otimes I \ket{\psi} -  \E_{\bx} \sum_b \bra{\psi} A^{\bx}_{[f(a)=b]} \otimes A^{\bx}_{[f(a)=b]} \ket{\psi}\Big).\label{eq:finishing-this-up}
 979	\end{align}
 980	The second term in \Cref{eq:finishing-this-up} can be bounded by
 981	\begin{align*}
 982	 \E_{\bx} \sum_b \bra{\psi} A^{\bx}_{[f(a)=b]} \otimes A^{\bx}_{[f(a)=b]} \ket{\psi}
 983	 &=  \E_{\bx} \sum_{a, a': f(a) = f(a')} \bra{\psi} A^{\bx}_{a} \otimes A^{\bx}_{a'} \ket{\psi}\\
 984	 &\geq\E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_{a} \otimes A^{\bx}_{a} \ket{\psi}\\
 985	 &\geq \bra{\psi} A \ot I \ket{\psi} -\delta.
 986	\end{align*}
 987	Hence,
 988	\begin{equation*}
 989	\eqref{eq:finishing-this-up} \leq 
 990		2\cdot \Big( \bra{\psi} A \otimes I \ket{\psi} - (\bra{\psi} A \ot I \ket{\psi} -\delta)\Big)
 991	= 2\delta.
 992	\end{equation*}
 993	This concludes the proof.
 994	\end{proof}
 995	
 996	
 997	
 998	
 999	\begin{proposition}\label{prop:completeness-transfer-self-consistent-A}
1000	Let $\ket{\psi}$ be a permutation-invariant state,
1001	and let $A = \{A^x_a\}$ be a sub-measurement such that
1002	\begin{equation*}
1003	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq  \bra{\psi} A \otimes I \ket{\psi} - \delta.
1004	\end{equation*}
1005	In addition, let $B$ be a sub-measurement such that $A^x_a \ot I \approx_{\eps} B_a^x \ot I$.
1006	Then
1007	\begin{equation*}
1008	\bra{\psi} B \ot I \ket{\psi}
1009	\geq \bra{\psi} A \ot I \ket{\psi} - \delta - 2\sqrt{\eps}.
1010	\end{equation*}
1011	\end{proposition}
1012	\begin{proof}
1013	We calculate:
1014	\begin{align*}
1015	\bra{\psi} B \ot I \ket{\psi}
1016	&= \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a \ot I \ket{\psi} \\
1017	&\geq \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a \ot B^{\bx}_a \ket{\psi} \\
1018	& \geq \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi} - \sqrt{\eps}
1019					\tag{by \Cref{prop:easy-approx-from-approx-delta}} \\
1020	& \geq \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot A^{\bx}_a \ket{\psi} - 2\sqrt{\eps}
1021					\tag{by \Cref{prop:easy-approx-from-approx-delta}} \\
1022	& \geq  \bra{\psi} A \ot I \ket{\psi} - \delta - 2\sqrt{\eps}.
1023	\end{align*}
1024	This completes the proof.
1025	\end{proof}
1026	
1027	
1028	\begin{proposition}\label{prop:self-consistency-implies-data-processing}
1029	Let $\ket{\psi}$ be a permutation-invariant state,
1030	and let $A = \{A^x_a\}$ be a sub-measurement such that
1031	\begin{equation*}
1032	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi} \geq  \bra{\psi} A \otimes I \ket{\psi} - \delta.
1033	\end{equation*}
1034	In addition, let $P$ be a projective sub-measurement such that $P^x_a \ot I \approx_{\eps} A_a^x \ot I$.
1035	Then for any function~$f$,
1036	\begin{equation*}
1037	P^x_{[f(a)=b]} \ot I \approx_{8\delta + 8\sqrt{\eps}} A_{[f(a)=b]}^x \ot I.
1038	\end{equation*}
1039	\end{proposition}
1040	\begin{proof}
1041	We will begin by showing that
1042	\begin{equation}\label{eq;what-we-want-to-prove-but-on-wrong-side}
1043	P^x_{[f(a)=b]} \ot I \approx_{2\delta + 4\sqrt{\eps}} I \ot A_{[f(a)=b]}^x.
1044	\end{equation}
1045	To do so, our goal is to bound
1046	\begin{align}
1047	&\E_{\bx} \sum_b \Vert(P^{\bx}_{[f(a)=b]} \ot I - I \ot A_{[f(a)=b]}^{\bx}) \ket{\psi} \Vert^2\nonumber\\
1048	=~&\E_{\bx} \sum_b \bra{\psi} (P^{\bx}_{[f(a)=b]}  \ot I -  I \ot A_{[f(a)=b]}^{\bx})^2 \ket{\psi} \nonumber\\
1049	=~&\E_{\bx} \sum_b \bra{\psi} \Big((P^{\bx}_{[f(a)=b]})^2 \ot I 
1050			+ I \ot (A^{\bx}_{[f(a)=b]})^2 
1051			- 2\cdot P^{\bx}_{[f(a)=b]} \ot A^{\bx}_{[f(a)=b]}\Big) \ket{\psi}\nonumber\\
1052	\leq~&\E_{\bx} \sum_b \bra{\psi} \Big(P^{\bx}_{[f(a)=b]} \ot I 
1053			+ I \ot A^{\bx}_{[f(a)=b]}
1054			- 2\cdot P^{\bx}_{[f(a)=b]} \ot A^{\bx}_{[f(a)=b]}\Big) \ket{\psi}\nonumber\\
1055	=~&\bra{\psi} P \ot I \ket{\psi} + \bra{\psi} I \ot A \ket{\psi}
1056			- 2\cdot \E_{\bx} \sum_b \bra{\psi}  P^{\bx}_{[f(a)=b]} \ot A^{\bx}_{[f(a)=b]} \ket{\psi}.
1057					\label{eq:gonna-handle-third-term}
1058	\end{align}
1059	By \Cref{prop:completeness-transfer-projective-P}, the first term in \Cref{eq:gonna-handle-third-term} is at most
1060	\begin{equation*}
1061	\bra{\psi} P \ot I \ket{\psi}
1062	\leq \bra{\psi} A \ot I \ket{\psi} + 2\sqrt{\eps}.
1063	\end{equation*}
1064	As for the third term in \Cref{eq:gonna-handle-third-term}, we can bound it by
1065	\begin{align*}
1066	\E_{\bx} \sum_b \bra{\psi}  P^{\bx}_{[f(a)=b]} \ot A^{\bx}_{[f(a)=b]} \ket{\psi}
1067	&= \E_{\bx} \sum_{a, a': f(a) = f(a')} \bra{\psi}  P^{\bx}_{a} \ot A^{\bx}_{a'} \ket{\psi}\\
1068	&\geq \E_{\bx} \sum_{a} \bra{\psi}  P^{\bx}_{a} \ot A^{\bx}_{a} \ket{\psi}\\
1069	&\geq \E_{\bx} \sum_{a} \bra{\psi}  A^{\bx}_{a} \ot A^{\bx}_{a} \ket{\psi} - \sqrt{\eps}
1070							\tag{by \Cref{prop:easy-approx-from-approx-delta}} \\
1071	&\geq \bra{\psi} A \otimes I \ket{\psi} - \delta - \sqrt{\eps}.
1072	\end{align*}
1073	Putting everything together,
1074	\begin{equation*}
1075	\eqref{eq:gonna-handle-third-term}
1076	\leq (\bra{\psi} A \ot I \ket{\psi} + 2\sqrt{\eps}) + \bra{\psi} A \ot I \ket{\psi}
1077		- 2 \cdot(\bra{\psi} A \otimes I \ket{\psi} - \delta - \sqrt{\eps})
1078	= 2\delta + 4\sqrt{\eps}.
1079	\end{equation*}
1080	This proves \Cref{eq;what-we-want-to-prove-but-on-wrong-side}.
1081	
1082	
1083	\Cref{prop:two-notions-of-self-consistency-after-evaluation} implies that
1084	\begin{equation*}
1085	A^x_{[f(a)=b]} \ot I \approx_{2\delta} I \ot A^x_{[f(a)=b]}.
1086	\end{equation*}
1087	Hence, by \Cref{eq;what-we-want-to-prove-but-on-wrong-side},
1088	\begin{equation*}
1089	P^x_{[f(a)=b]} \ot I
1090	\approx_{2\delta + 4\sqrt{\eps}} I \ot A_{[f(a)=b]}^x
1091	\approx_{2\delta} A^x_{[f(a)=b]} \ot I.
1092	\end{equation*}
1093	Thus, by \Cref{prop:triangle-inequality-for-approx_delta},
1094	\begin{equation*}
1095	P^x_{[f(a)=b]} \ot I
1096	\approx_{8\delta + 8\sqrt{\eps}}A^x_{[f(a)=b]} \ot I.
1097	\end{equation*}
1098	This concludes the proof.
1099	\end{proof}
1100	
1101	\begin{proposition}\label{prop:completing-to-measurement}
1102			Let $\ket{\psi}$ be a permutation-invariant state,
1103			and let $A = \{A_a\}$ be a measurement such that
1104			\begin{equation*}
1105			\E_{\bx} \sum_a \bra{\psi} A_a \otimes A_a \ket{\psi} \geq  \bra{\psi} A \otimes I \ket{\psi} - \zeta.
1106			\end{equation*}
1107			Suppose $B = \{B_a\}$ is a sub-measurement such that
1108			$A_a\ot I \approx_{\delta} B_a\ot I$.
1109			Let $C = \{C_a\}$ be a measurement in which there is an~$a^*$
1110			such that $C_{a^*} = B_{a^*} + (I-B)$ and $C_a = B_a$ for all $a \neq a^*$.
1111			Then $A_a \ot I \approx_{2\delta + 4 \sqrt{\delta} + 2\zeta} C_a \ot I$.
1112			\end{proposition}
1113			
1114			Before proving this, we need the following proposition.
1115			\begin{proposition}\label{prop:cool-prop}
1116			Let $\ket{\psi}$ be a permutation-invariant state,
1117			and let $A = \{A_a\}$ be a sub-measurement such that
1118			\begin{equation*}
1119			\E_{\bx} \sum_a \bra{\psi} A_a \otimes A_a \ket{\psi} \geq  \bra{\psi} A \otimes I \ket{\psi} - \zeta.
1120			\end{equation*}
1121			Then
1122			\begin{equation*}
1123			\sum_a \bra{\psi} (A_a)^2 \otimes I \ket{\psi} \geq \sum_a \bra{\psi} A_a \otimes I \ket{\psi} -\zeta.
1124			\end{equation*}
1125			\end{proposition}
1126			\begin{proof}
1127			Applying Cauchy-Schwarz, we have
1128	\begin{align}
1129	\sum_a \bra{\psi} A_a \otimes A_a \ket{\psi}
1130	&= \sum_a \bra{\psi} (A_a \ot I) \cdot (I \ot A_a) \ket{\psi}\nonumber\\
1131	&\leq \sqrt{\sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi}} \cdot \sqrt{\sum_a \bra{\psi} I \ot (A_a)^2 \ket{\psi}}\nonumber\\
1132	& = \sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi}.\label{eq:As-on-same-side-rewrite}
1133	\end{align}
1134	As a result,
1135	\begin{align*}
1136	\sum_a \bra{\psi} (A_a)^2 \otimes I \ket{\psi}
1137	&\geq \sum_a \bra{\psi} A_a \otimes A_a \ket{\psi}\tag{by \Cref{eq:As-on-same-side-rewrite}}\\
1138	&\geq \sum_a \bra{\psi} A_a \otimes I \ket{\psi} -\zeta. \tag{by self-consistency of~$A$}
1139	\end{align*}
1140	This completes the proof.
1141	\end{proof}
1142			Now we prove \Cref{prop:completing-to-measurement}.
1143			\begin{proof}[Proof of \Cref{prop:completing-to-measurement}]
1144			By \Cref{prop:triangle-inequality-for-vectors-squared} (the triangle inequality for vectors squared),
1145			\begin{align*}
1146			&\phantom{=}\sum_a \Vert(A_a - C_a)\ot I \ket{\psi} \Vert^2\\
1147			& = \sum_{a \neq a^*} \Vert(A_a - B_a)\ot I \ket{\psi} \Vert^2 + \Vert(A_{a^*}  - (I-B + B_{a^*}))\ot I\ket{\psi}\Vert^2\\
1148			& \leq \sum_{a \neq a^*} \Vert(A_a - B_a)\ot I \ket{\psi} \Vert^2 + 2 \cdot \Vert(A_{a^*}  -  B_{a^*})\ot I\ket{\psi}\Vert^2 + 2 \cdot \Vert(I - B) \ot I\ket{\psi}\Vert^2\\
1149			& \leq 2\sum_{a \neq a^*} \Vert(A_a - B_a)\ot I \ket{\psi} \Vert^2 + 2 \cdot \Vert(A_{a^*}  -  B_{a^*})\ot I\ket{\psi}\Vert^2 + 2 \cdot \Vert(I - B) \ot I\ket{\psi}\Vert^2\\
1150			& = 2\sum_{a} \Vert(A_a - B_a)\ot I \ket{\psi} \Vert^2 + 2 \cdot \Vert(I - B)\ot I \ket{\psi}\Vert^2\\
1151			& \leq 2 \delta + 2 \cdot \Vert(I - B)\ot I \ket{\psi}\Vert^2. \tag{because $A_a \ot I \approx_{\delta} B_a \ot I$}
1152			\end{align*}
1153			The second term we can bound as follows.
1154			\begin{align}
1155			\Vert(I - B) \ot I \ket{\psi}\Vert^2
1156			& = \bra{\psi} (I-B)^2 \ot I \ket{\psi}\nonumber\\
1157			& \leq \bra{\psi} (I-B)\ot I \ket{\psi} \tag{because~$B$ is a sub-measurement}\\
