1166			& \approx_{\sqrt{\delta}} \sum_a \bra{\psi} A_a^2\ot I \ket{\psi}\\
1167			& \geq  \bra{\psi} A \ot I \ket{\psi}- \zeta \tag{by \Cref{prop:cool-prop}}\\
1168			& = 1 - \zeta. \tag{because~$A$ is a measurement}
1169			\end{align*}
