1171			\begin{equation*}
1172			\Vert(I - B) \ot I \ket{\psi}\Vert^2 \leq 1 -\sum_a \bra{\psi} B_a^2 \ot I \ket{\psi} \leq 2\sqrt{\delta} + \zeta.
1173			\end{equation*}
